import{_ as o,o as n,c as i,a0 as s,j as a,a as t,t as r}from"./chunks/framework.Cg_noeTw.js";const v=JSON.parse('{"title":"Decisions","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/decisions.md","filePath":"explanation/decisions.md"}'),l={name:"explanation/decisions.md"};function c(d,e,m,u,p,h){return n(),i("div",null,[e[6]||(e[6]=s('<h1 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h1><p>ADR-lite: the load-bearing decisions, each with the alternative it beat and the consequence it carries. Design history lives in the org ledger — proposal P-017 (supersedes P-015).</p><h2 id="generic-over-t-never-a-consumer-s-model" tabindex="-1">Generic over <code>T</code>, never a consumer&#39;s model <a class="header-anchor" href="#generic-over-t-never-a-consumer-s-model" aria-label="Permalink to &quot;Generic over `T`, never a consumer&#39;s model&quot;">​</a></h2><p><strong>Decision:</strong> <code>ConfigSource&lt;T&gt;</code>/<code>ConfigFormat&lt;T&gt;</code> are generic over the consumer&#39;s serde model — scarab never names a <code>Config</code> type.</p><ul><li><em>Alternative:</em> a scarab-owned universal config schema.</li><li><em>Consequence:</em> one <code>FileSource</code> serves myco, tamias, tarsi, and every future repo; each consumer keeps only its serde model. Cost: trait objects at the call site to keep generics from exploding.</li></ul><h2 id="discovery-is-a-spec-not-a-search-loop" tabindex="-1">Discovery is a spec, not a search loop <a class="header-anchor" href="#discovery-is-a-spec-not-a-search-loop" aria-label="Permalink to &quot;Discovery is a spec, not a search loop&quot;">​</a></h2><p><strong>Decision:</strong> <code>Discovery</code> declares <code>env_var</code>, <code>dirs</code>, format preference, explicit-path handling; <code>FileSource</code> interprets it.</p><ul><li><em>Alternative:</em> hard-coded per-repo search logic (the <code>gen-*.py</code>/copy-paste status quo).</li><li><em>Consequence:</em> env/remote <code>ConfigSource</code> impls reuse the same vocabulary without inheriting file semantics.</li></ul><h2 id="formats-are-separate-crates" tabindex="-1">Formats are separate crates <a class="header-anchor" href="#formats-are-separate-crates" aria-label="Permalink to &quot;Formats are separate crates&quot;">​</a></h2><p><strong>Decision:</strong> <code>scarab-config-toml</code> and <code>-yaml</code> own only syntax; <code>scarab-config</code> stays pure (traits, <code>Discovery</code>, merge helpers).</p><ul><li><em>Alternative:</em> one crate with all formats baked in.</li><li><em>Consequence:</em> a consumer carries just the syntax it wants; the port stays I/O-free and unit-testable.</li></ul><h2 id="config-and-templates-are-separate-planes" tabindex="-1">Config and templates are separate planes <a class="header-anchor" href="#config-and-templates-are-separate-planes" aria-label="Permalink to &quot;Config and templates are separate planes&quot;">​</a></h2><p><strong>Decision:</strong> config is <em>read</em> (find, parse, model); templates are <em>write</em> (render sources to targets with a var context) — two ports, two invariants.</p><ul><li><em>Alternative:</em> one unified &quot;content&quot; port.</li><li><em>Consequence:</em> a consumer adopts one plane without the other; discovery order vs. path-safety+digest invariants stay local.</li></ul><h2 id="minijinja-is-the-only-engine-v1" tabindex="-1">MiniJinja is the only engine (v1) <a class="header-anchor" href="#minijinja-is-the-only-engine-v1" aria-label="Permalink to &quot;MiniJinja is the only engine (v1)&quot;">​</a></h2><p><strong>Decision:</strong> <code>scarab-template-minijinja</code> is deliberately the sole <code>TemplateEngine</code> impl — sandboxed by construction.</p>',16)),a("ul",null,[e[5]||(e[5]=a("li",null,[a("em",null,"Alternative:"),t(" a plugin system for template syntax.")],-1)),a("li",null,[e[0]||(e[0]=a("em",null,"Consequence:",-1)),e[1]||(e[1]=t()),a("code",null,r(),1),e[2]||(e[2]=t("/",-1)),e[3]||(e[3]=a("code",null,"{% %}",-1)),e[4]||(e[4]=t(" covers config-file templating without attack surface; the port exists so a second syntax family can land without touching model or driver.",-1))])]),e[7]||(e[7]=s('<h2 id="uninstall-is-digest-exact" tabindex="-1">Uninstall is digest-exact <a class="header-anchor" href="#uninstall-is-digest-exact" aria-label="Permalink to &quot;Uninstall is digest-exact&quot;">​</a></h2><p><strong>Decision:</strong> the driver records sha256 per written file; uninstall removes only files still matching.</p><ul><li><em>Alternative:</em> remove everything the pack declared.</li><li><em>Consequence:</em> user edits survive uninstall and are reported — templated files are owned only until touched.</li></ul><h2 id="secrets-stay-names" tabindex="-1">Secrets stay names <a class="header-anchor" href="#secrets-stay-names" aria-label="Permalink to &quot;Secrets stay names&quot;">​</a></h2><p><strong>Decision:</strong> config surfaces and template vars carry secret <em>names</em>, never values; cuora owns resolution.</p><ul><li><em>Alternative:</em> templated secret injection.</li><li><em>Consequence:</em> packs are safe to distribute and review; the boundary is convention plus cuora owning the values.</li></ul>',6))])}const f=o(l,[["render",c]]);export{v as __pageData,f as default};
